#include <algorithm>
#include <cstdint>
#include <optional>
#include <string>
#include <vector>

struct Request { std::string name; std::uint32_t hosts; };
struct Allocation { std::string name; std::uint32_t network; int prefix; };

static std::uint32_t maskOf(int prefix) { return prefix <= 0 ? 0u : prefix >= 32 ? 0xFFFFFFFFu : ~((1u << (32 - prefix)) - 1u); }

static std::string dotted(std::uint32_t a)
{
    return std::to_string(a >> 24) + "." + std::to_string((a >> 16) & 0xFF) + "." + std::to_string((a >> 8) & 0xFF) + "." + std::to_string(a & 0xFF);
}

int prefixFor(std::uint32_t hosts)
{
    if (hosts == 0) return -1;
    for (int p{ 30 }; p >= 1; --p)
        if ((std::uint64_t{ 1 } << (32 - p)) - 2 >= hosts) return p;
    return -1;
}

std::optional<std::vector<Allocation>> plan(std::uint32_t base, int basePrefix, const std::vector<Request>& requests)
{
    struct Item { std::string name; int prefix; };
    std::vector<Item> items;
    for (const Request& r : requests)
    {
        const int p{ prefixFor(r.hosts) };
        if (p < 0 || p < basePrefix) return std::nullopt;
        items.push_back({ r.name, p });
    }
    std::stable_sort(items.begin(), items.end(), [](const Item& a, const Item& b) { return a.prefix < b.prefix; });
    const std::uint64_t start{ base & maskOf(basePrefix) };
    const std::uint64_t end{ start + (std::uint64_t{ 1 } << (32 - basePrefix)) };
    std::uint64_t next{ start };
    std::vector<Allocation> out;
    for (const Item& item : items)
    {
        const std::uint64_t size{ std::uint64_t{ 1 } << (32 - item.prefix) };
        if (next + size > end) return std::nullopt;
        out.push_back({ item.name, static_cast<std::uint32_t>(next), item.prefix });
        next += size;
    }
    return out;
}

std::string describe(const Allocation& a)
{
    const std::uint32_t broadcast{ a.network | ~maskOf(a.prefix) };
    return a.name + " " + dotted(a.network) + "/" + std::to_string(a.prefix) + " hosts " + dotted(a.network + 1) + "-" + dotted(broadcast - 1) + " broadcast " + dotted(broadcast);
}

unitTests:
static std::uint32_t ip(int a, int b, int c, int d) { return (static_cast<std::uint32_t>(a) << 24) | (b << 16) | (c << 8) | d; }
TEST("subnet sizes") {
    CHECK_EQ(prefixFor(1), 30); CHECK_EQ(prefixFor(2), 30); CHECK_EQ(prefixFor(3), 29);
    CHECK_EQ(prefixFor(62), 26); CHECK_EQ(prefixFor(63), 25);
    CHECK_EQ(prefixFor(254), 24); CHECK_EQ(prefixFor(255), 23);
    CHECK_EQ(prefixFor(0), -1);
    CHECK_EQ(prefixFor(0xFFFFFFFFu), -1);
}
TEST("a plan for an office") {
    const auto p{ plan(ip(10, 0, 0, 77), 24, { { "link", 2 }, { "office", 100 }, { "guests", 20 }, { "lab", 50 } }) };
    CHECK(p.has_value());
    if (!p || p->size() != 4) { CHECK(false); return; }
    CHECK_EQ(describe((*p)[0]), std::string("office 10.0.0.0/25 hosts 10.0.0.1-10.0.0.126 broadcast 10.0.0.127"));
    CHECK_EQ(describe((*p)[1]), std::string("lab 10.0.0.128/26 hosts 10.0.0.129-10.0.0.190 broadcast 10.0.0.191"));
    CHECK_EQ(describe((*p)[2]), std::string("guests 10.0.0.192/27 hosts 10.0.0.193-10.0.0.222 broadcast 10.0.0.223"));
    CHECK_EQ(describe((*p)[3]), std::string("link 10.0.0.224/30 hosts 10.0.0.225-10.0.0.226 broadcast 10.0.0.227"));
}
TEST("equal sizes keep their order") {
    const auto p{ plan(ip(192, 168, 4, 0), 22, { { "a", 200 }, { "b", 200 }, { "c", 200 }, { "d", 200 } }) };
    CHECK(p.has_value());
    if (p && p->size() == 4) { CHECK_EQ((*p)[2].name, std::string("c")); CHECK_EQ((*p)[3].network, ip(192, 168, 7, 0)); }
}
TEST("plans that do not fit") {
    CHECK(!plan(ip(10, 0, 0, 0), 24, { { "big", 200 }, { "more", 100 } }).has_value());
    CHECK(!plan(ip(10, 0, 0, 0), 24, { { "huge", 300 } }).has_value());
    CHECK(!plan(ip(10, 0, 0, 0), 24, { { "none", 0 } }).has_value());
    const auto empty{ plan(ip(10, 0, 0, 0), 24, {}) };
    CHECK(empty.has_value());
    if (empty) CHECK(empty->empty());
}

